// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g, uint256 extra) public {
        vm.assume(actor != address(0) && actor != address(c));
        extra = bound(extra, 4 ether, 100 ether);

        // fund the contract so the 2 ether payout can succeed
        vm.deal(address(c), extra);

        // lock in a guess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // move past the target block
        vm.roll(block.number + 2);

        bool ok1;
        vm.prank(actor);
        try c.settle() { ok1 = true; } catch { ok1 = false; }

        vm.roll(block.number + 1);

        bool ok2;
        vm.prank(actor);
        try c.settle() { ok2 = true; } catch { ok2 = false; }

        // Rule: once settle() has completed successfully, any further settle()
        // by the same caller must revert (the guess was consumed).
        assertTrue(!(ok1 && ok2));
    }
}
